<?php
declare(strict_types=1);
require_once __DIR__ . '/../app/bootstrap.php';
use BAJAMA\Core\Auth; use BAJAMA\Core\License; use BAJAMA\Core\RBAC; use BAJAMA\Core\Tenant;
 Auth::requireLogin(); $db=db(); License::requireFeature($db,'mikrotik'); RBAC::require($db,'network.view'); $organizationId=Tenant::id(); $canManage=RBAC::hasPermission($db,'network.manage'); $message='';$error='';$editId=(int)($_GET['edit']??0);$edit=null;
if($editId){$s=$db->prepare('SELECT * FROM network_firewall_rules WHERE id=? AND organization_id=?');$s->execute([$editId,$organizationId]);$edit=$s->fetch(PDO::FETCH_ASSOC)?:null;}
if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf((string)($_POST['_csrf']??$_POST['csrf']??''));if(!$canManage)throw new RuntimeException('Anda tidak memiliki izin mengelola firewall.');$action=(string)($_POST['action']??'');$id=(int)($_POST['id']??0);if($action==='delete'||$action==='toggle'){ $q=$action==='delete'?'DELETE FROM network_firewall_rules WHERE id=? AND organization_id=?':'UPDATE network_firewall_rules SET enabled=CASE WHEN enabled=1 THEN 0 ELSE 1 END WHERE id=? AND organization_id=?';$db->prepare($q)->execute([$id,$organizationId]);$message=$action==='delete'?'Rule firewall dihapus.':'Status rule firewall diubah.';}elseif($action==='save'){$router=(int)($_POST['router_id']??0);$chain=strtoupper((string)($_POST['chain']??'FORWARD'));$ruleAction=strtoupper((string)($_POST['rule_action']??'ACCEPT'));$protocol=strtoupper((string)($_POST['protocol']??'ANY'));$src=trim((string)($_POST['src_address']??''));$dst=trim((string)($_POST['dst_address']??''));$srcPort=trim((string)($_POST['src_port']??''));$dstPort=trim((string)($_POST['dst_port']??''));$position=max(1,(int)($_POST['position']??100));$comment=trim((string)($_POST['comment']??''));if(!$router||!in_array($chain,['INPUT','FORWARD','OUTPUT'],true)||!in_array($ruleAction,['ACCEPT','DROP','REJECT','FASTTRACK','LOG'],true)||!in_array($protocol,['ANY','TCP','UDP','ICMP'],true))throw new RuntimeException('Data firewall tidak valid.');$c=$db->prepare('SELECT id FROM mikrotik_routers WHERE id=? AND organization_id=?');$c->execute([$router,$organizationId]);if(!$c->fetchColumn())throw new RuntimeException('Router bukan milik organisasi.');$p=[$router,$chain,$ruleAction,$protocol,$src?:null,$dst?:null,$srcPort?:null,$dstPort?:null,$position,$comment?:null];if($id){$db->prepare('UPDATE network_firewall_rules SET router_id=?,chain=?,action=?,protocol=?,src_address=?,dst_address=?,src_port=?,dst_port=?,position=?,comment=? WHERE id=? AND organization_id=?')->execute([...$p,$id,$organizationId]);}else{$db->prepare('INSERT INTO network_firewall_rules (organization_id,router_id,chain,action,protocol,src_address,dst_address,src_port,dst_port,position,comment) VALUES (?,?,?,?,?,?,?,?,?,?,?)')->execute([$organizationId,...$p]);}$message='Rule firewall berhasil disimpan.';}}catch(Throwable $e){$error=$e->getMessage();}}
$r=$db->prepare('SELECT id,name FROM mikrotik_routers WHERE organization_id=? ORDER BY name');$r->execute([$organizationId]);$routers=$r->fetchAll(PDO::FETCH_ASSOC);$s=$db->prepare('SELECT f.*,r.name router_name FROM network_firewall_rules f JOIN mikrotik_routers r ON r.id=f.router_id AND r.organization_id=f.organization_id WHERE f.organization_id=? ORDER BY f.position,f.id');$s->execute([$organizationId]);$items=$s->fetchAll(PDO::FETCH_ASSOC);function fw_h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}$pageTitle='Firewall';$networkLayout=true;$networkActive='firewall';ob_start();
?>
<div class="container-fluid py-4"><div class="mb-4"><h1>Firewall</h1><p class="text-muted mb-0">Rule firewall tenant per router, chain, protocol, alamat dan port.</p></div><?php if($message):?><div class="alert alert-success"><?=fw_h($message)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=fw_h($error)?></div><?php endif;?><div class="card mb-4"><div class="card-body"><h2 class="h5"><?= $edit?'Edit Rule Firewall':'Tambah Rule Firewall' ?></h2><form method="post" class="row g-3"><input type="hidden" name="_csrf" value="<?=fw_h(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><div class="col-md-2"><label class="form-label">Router</label><select class="form-select" name="router_id" required><?php foreach($routers as $r):?><option value="<?=$r['id']?>" <?=((int)($edit['router_id']??0)==$r['id']?'selected':'')?>><?=fw_h($r['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">Chain</label><select class="form-select" name="chain"><?php foreach(['INPUT','FORWARD','OUTPUT'] as $v):?><option <?=$v===($edit['chain']??'FORWARD')?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">Action</label><select class="form-select" name="rule_action"><?php foreach(['ACCEPT','DROP','REJECT','FASTTRACK','LOG'] as $v):?><option <?=$v===($edit['action']??'ACCEPT')?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">Protocol</label><select class="form-select" name="protocol"><?php foreach(['ANY','TCP','UDP','ICMP'] as $v):?><option <?=$v===($edit['protocol']??'ANY')?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">Position</label><input class="form-control" type="number" name="position" value="<?=fw_h($edit['position']??100)?>"></div><div class="col-md-2"><label class="form-label">Source address</label><input class="form-control" name="src_address" value="<?=fw_h($edit['src_address']??'')?>"></div><div class="col-md-2"><label class="form-label">Destination address</label><input class="form-control" name="dst_address" value="<?=fw_h($edit['dst_address']??'')?>"></div><div class="col-md-2"><label class="form-label">Source port</label><input class="form-control" name="src_port" value="<?=fw_h($edit['src_port']??'')?>"></div><div class="col-md-2"><label class="form-label">Destination port</label><input class="form-control" name="dst_port" value="<?=fw_h($edit['dst_port']??'')?>"></div><div class="col-md-3"><label class="form-label">Comment</label><input class="form-control" name="comment" value="<?=fw_h($edit['comment']??'')?>"></div><div class="col-md-1 d-flex align-items-end"><button class="btn btn-primary" <?=$canManage?'':'disabled'?>>Simpan</button></div></form></div></div><div class="card"><div class="table-responsive"><table class="table table-sm table-hover mb-0"><thead><tr><th>#</th><th>Router</th><th>Chain</th><th>Action</th><th>Protocol</th><th>Source</th><th>Destination</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=$i['position']?></td><td><?=fw_h($i['router_name'])?></td><td><?=$i['chain']?></td><td><?=$i['action']?></td><td><?=$i['protocol']?></td><td><?=fw_h($i['src_address'])?>:<?=fw_h($i['src_port'])?></td><td><?=fw_h($i['dst_address'])?>:<?=fw_h($i['dst_port'])?></td><td><?=$i['enabled']?'ENABLED':'DISABLED'?></td><td><a class="btn btn-sm btn-outline-primary" href="network_firewall.php?edit=<?=$i['id']?>">Edit</a><form method="post" class="d-inline"><input type="hidden" name="_csrf" value="<?=fw_h(csrf_token())?>"><input type="hidden" name="id" value="<?=$i['id']?>"><button name="action" value="toggle" class="btn btn-sm btn-outline-warning">Enable/Disable</button><button name="action" value="delete" class="btn btn-sm btn-outline-danger" onclick="return confirm('Hapus rule?')">Hapus</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div>
